WITH head AS MATERIALIZED (
 SELECT coalesce((SELECT revision FROM public.inbox_inbound_heads WHERE org_id='c40614d1-3fa5-4bd8-ae90-ce2bd636c68d' AND conversation_id='14f6f003-53c5-4184-a2e2-7dedc78178f4'),0)::text AS revision
), history AS MATERIALIZED (
 SELECT id,created_at::text AS created_at_raw,inbox_inbound_revision::text AS inbound_revision,direction,read_at::text AS read_at_raw
 FROM public.messages WHERE org_id='c40614d1-3fa5-4bd8-ae90-ce2bd636c68d' AND conversation_id='14f6f003-53c5-4184-a2e2-7dedc78178f4' AND channel='sms'
 ORDER BY created_at DESC,id DESC LIMIT 50
) SELECT json_build_object('head',(SELECT revision FROM head),'history',coalesce((SELECT json_agg(row_to_json(h) ORDER BY h.created_at_raw::timestamptz DESC,h.id DESC) FROM history h),'[]'::json));

sql_batch:
WITH eligible AS MATERIALIZED (
 SELECT id FROM public.messages WHERE org_id='c40614d1-3fa5-4bd8-ae90-ce2bd636c68d' AND conversation_id='14f6f003-53c5-4184-a2e2-7dedc78178f4' AND channel='sms' AND direction='inbound' AND read_at IS NULL AND inbox_inbound_revision <= 451::bigint
 ORDER BY id LIMIT 200 FOR UPDATE
), changed AS (
 UPDATE public.messages m SET read_at=statement_timestamp() FROM eligible e WHERE m.id=e.id
 AND m.org_id='c40614d1-3fa5-4bd8-ae90-ce2bd636c68d' AND m.conversation_id='14f6f003-53c5-4184-a2e2-7dedc78178f4' AND m.channel='sms' AND m.direction='inbound' AND m.read_at IS NULL AND m.inbox_inbound_revision <= 451::bigint RETURNING m.id
) SELECT count(*) FROM changed;
